class Solution {
public:
    int maximumGroups(vector<int>& grades) {
        int n = grades.size();
        int lo = 1, hi = n, ans = 0;
        while (lo <= hi) {
            long long mid = lo + (hi - lo) / 2;
            if (mid * (mid + 1) / 2 <= n) {
                ans = mid;
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        return ans;
    }
};
